        expectedList.add("sdfsd");
        expectedList.add("dcwqerba");
        List<String> expectedList1 = new ArrayList<>(expectedList);
        expectedList1.addAll(index, other);

        DoublyLinkedList<String> sourceList = createDoublyLinkedList(other);



        DoublyLinkedList<String> list= createDoublyLinkedList(expectedList);
        list.moveFrom(index, sourceList);

